changeSet.sql:
CREATE OR REPLACE FUNCTION landvault_release_plot( p_plot_id uuid, p_restore_status varchar, p_actor varchar) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE v_tier_type varchar; v_tier_size numeric; BEGIN -- The status is caller-supplied, so it is validated here -- rather than trusted. Without this, a definer function that -- writes plots.status would be a way to mark any held plot -- SOLD without a payment, from a buyer's own session. IF p_restore_status NOT IN ('AVAILABLE_DEV', 'AVAILABLE_INV') THEN RAISE EXCEPTION 'landvault_release_plot: refusing to set plot status to %', p_restore_status; END IF;
-- FOR SHARE on the tier: a size edit in flight holds the tier -- row's lock, so this waits for it to commit and then reads -- the NEW size. Without the lock, a release racing a size -- edit could read the old size, return the plot to the pool -- after the edit's plot UPDATE had already skipped it (it was -- still RESERVED then), and leave it permanently out of step. SELECT pt.tier_type, pt.size_sqm INTO v_tier_type, v_tier_size FROM plots p JOIN price_tiers pt ON pt.id = p.price_tier_id WHERE p.id = p_plot_id FOR SHARE OF pt;
UPDATE plots p SET status = p_restore_status, nominal_size_sqm = CASE WHEN v_tier_type = 'LAND_SIZE' THEN v_tier_size ELSE p.nominal_size_sqm END, updated_at = now(), updated_by = p_actor WHERE p.id = p_plot_id AND p.deleted = false AND p.status = 'RESERVED';
RETURN FOUND; END; $$;

rollback.sql:
CREATE OR REPLACE FUNCTION landvault_release_plot( p_plot_id uuid, p_restore_status varchar, p_actor varchar) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF p_restore_status NOT IN ('AVAILABLE_DEV', 'AVAILABLE_INV') THEN RAISE EXCEPTION 'landvault_release_plot: refusing to set plot status to %', p_restore_status; END IF;
UPDATE plots p SET status = p_restore_status, updated_at = now(), updated_by = p_actor WHERE p.id = p_plot_id AND p.deleted = false AND p.status = 'RESERVED';
RETURN FOUND; END; $$;
